sited.script:

    // 核心的「內容列表」解析函式
    function list_parse(url, jsontext) {
        try {
            const response = JSON.parse(jsontext);
            if (!response || !response.data || !Array.isArray(response.data.items)) {
                return JSON.stringify([]);
            }
            const list = response.data.items.map(item => ({
                logo: item.thumbnail.replace(/^http:/, 'https:'),
                name: gbk2big5.traditionalized(item.title),
                // API 回傳的 URL 可能是 http，手動換成 https 增加安全性
                url: item.url.replace(/^http:/, 'https:')
            }));
            return JSON.stringify(list);
        } catch (error) {
            return JSON.stringify([]);
        }
    }

    // 解析文章詳情頁 (Book)，僅作導航用途
    function book_parse(url, html) {
        const $ = cheerio.load(html);
        const name = $('meta[property="og:title"]').attr('content') || $('title').text();
        const logo = $('meta[property="og:image"]').attr('content');
        const sections = [{
            name: "閱讀全文",
            url: url.replace(/^http:/, 'https:')
        }];
        const book = {
            name: gbk2big5.traditionalized(name),
            logo: logo,
            intro: gbk2big5.traditionalized("點擊下方 '閱讀全文' 開始閱讀"),
            sections: sections
        };
        return JSON.stringify(book);
    }

// ⭐【核心修正 V10 - 解決圖文順序問題】解析文章內容頁 (Section)
function section_parse(url, html) {
    const $ = cheerio.load(html);
    const data = [];

    // 找到文章的主要容器
    const articleContent = $('article#article-detail-content');

    if (articleContent.length === 0) {
        return JSON.stringify({type:"article", data: data});
    }

    // 遍歷文章內容的所有直接子元素 (<p>, <center>, <div>, etc.)
    articleContent.children().each(function() {
        const element = $(this);

        // ----------------------------------------------------
        // 1. 處理嵌入元素 (div.twitter-tweet) - 在這裡先處理非圖文的頂級元素
        // ----------------------------------------------------
        if (element.is('div')) {
             const elementClass = element.attr('class') || '';
             if (elementClass.includes('twitter-tweet')) {
                const elementHtml = element.html() || '';
                const $$$$ = cheerio.load(elementHtml);
                const iframe = $$$$('iframe');
                if (iframe.length > 0) {
                    data.push({ t: "text", d: gbk2big5.traditionalized("[外部內容: 嵌入式內容]") });
                    return; // 處理完畢，跳過這個 DIV
                }
             }
        }

        // ----------------------------------------------------
        // 2. 處理圖文混合元素 (P 或 CENTER)
        // ----------------------------------------------------
        // 我們將整個元素的 HTML 重新載入，並遍歷它的所有內容節點。
        const elementHtml = element.html() || '';
        const $$ = cheerio.load(elementHtml);

        // **關鍵步驟：遍歷元素內部的所有頂級節點 (包括文本節點)**
        $$.root().contents().each(function() {
            const node = $$(this);
            // 嘗試獲取節點類型，由於 Cheerio 限制，我們可能需要依賴 this.type
            const nodeType = this.type; 

            // 2.1 處理圖片節點
            if (nodeType === 'tag' && node.is('img')) {
                let src = node.attr('src') || node.attr('data-src');
                if (src) {
                    if (src.startsWith('//')) {
                        src = 'https:' + src;
                    }
                    src = src.replace(/^http:/, 'https:');

                    if (!src.includes('default_thumbnail.png')) {
                        data.push({ t: "image", d: src });
                    }
                }
            }

            // 2.2 處理文本節點 (文本, strong, span, a, br)
            else if (nodeType === 'text' || node.is('strong') || node.is('span') || node.is('a') || node.is('br') || node.is('center')) {

                // 由於文本, span, strong, a, br 都在一起，我們需要手動提取和清理
                // 我們只在遇到 <br> 時才應該將累積的文本輸出

                let currentHtml = node.toString(); // 獲取當前節點的原始 HTML/文本

                // 臨時標記 <strong> 內部的內容
                currentHtml = currentHtml.replace(/<strong[^>]*>([\s\S]*?)<\/strong>/gi, '@@BOLD@@$1@@/BOLD@@');

                // 移除 a/span/font 標籤，保留內容
                currentHtml = currentHtml.replace(/<span[^>]*>([\s\S]*?)<\/span>/gi, '$1'); 
                currentHtml = currentHtml.replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, '$1'); 
                currentHtml = currentHtml.replace(/<font[^>]*>([\s\S]*?)<\/font>/gi, '$1'); 

                // 移除所有其他不必要的 HTML 標籤 (除了 BR)
                let text = currentHtml.replace(/<(?!\/?br\s*\/?)[^>]+>/gi, '');

                // 將 <br> 替換為換行符，以便分段
                text = text.replace(/<br\s*\/?>/gi, '\n').trim(); 

                if (text) {
                    const lines = text.split('\n');

                    lines.forEach(line => {
                        line = line.trim();
                        if (line) {
                            // 分割出粗體和普通文本段落
                            const parts = line.split(/(@@BOLD@@.*?@@\/BOLD@@)/g).filter(p => p.trim() !== '');

                            parts.forEach(part => {
                                let partIsBold = part.startsWith('@@BOLD@@');
                                let partText = part.replace(/@@BOLD@@|@@\/BOLD@@/g, '').trim(); 

                                if (partText) {
                                    // 使用 V9 的解碼技巧
                                    let decodedText = cheerio.load('<div>' + partText + '</div>')('div').text();

                                    let item = { t: "text", d: gbk2big5.traditionalized(decodedText) };
                                    if (partIsBold) {
                                        item.b = 1;
                                    }
                                    data.push(item);
                                }
                            });
                        }
                    });
                }
            }
            // 忽略其他標籤 (如 <center> 容器本身，因為我們已經遍歷它的內容)

        });

    });

    return JSON.stringify({type:"article", data: data});
}
